MS.hook('resource:keep', function (kind, url) {
  if (kind !== 'video') return true;
  var exts = MS.config.get('exts', ['.mp4', '.webm', '.mkv', '.mov', '.m4v', '.flv']);
  if (!exts || !exts.length) return true;
  var u = String(url || '').toLowerCase().split('#')[0].split('?')[0];
  var m = u.match(/\.([a-z0-9]{2,5})$/);
  if (!m) return true;
  var hit = '.' + m[1];
  for (var i = 0; i < exts.length; i++) {
    if (String(exts[i] || '').toLowerCase() === hit) return true;
  }
  var KNOWN = ['.mp4', '.webm', '.mkv', '.mov', '.m4v', '.flv', '.avi', '.wmv',
               '.ts', '.m3u8', '.mpd', '.3gp', '.ogv', '.rmvb', '.f4v'];
  if (KNOWN.indexOf(hit) >= 0) return false;
  return true;
});
